INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (129, 1, 'rwx 는 무엇일까', '파일 권한 `rwx` 에서 r, w, x 는 각각 무엇을 뜻할까요?', '읽기, 쓰기, 실행의 영어 첫 글자예요.', NULL, NULL, '[]', 'choice', '["r=삭제, w=이동, x=복사", "r=루트, w=사용자, x=그룹", "r=읽기(read), w=쓰기(write), x=실행(execute)", "r=재시작, w=대기, x=종료"]', 2, '세 글자가 한 묶음이고, 소유자·그룹·그 밖의 사람 세 묶음이 이어져 총 9글자(`rwxr-xr-x`)가 됩니다.', NULL, NULL, NULL, NULL),
  (129, 2, '권한 9글자 읽는 법', '`-rwxr-xr--` 에서 맨 앞 `-` 다음 9글자는 어떤 순서로 읽을까요?', '세 글자씩 끊어 읽어요.', NULL, NULL, '[]', 'choice', '["읽기 3글자, 쓰기 3글자, 실행 3글자", "소유자 3글자, 그룹 3글자, 그 밖의 사람 3글자", "파일 3글자, 폴더 3글자, 링크 3글자", "오늘, 어제, 그제"]', 1, '`rwx`(소유자) `r-x`(그룹) `r--`(그 밖의 사람) 으로 읽습니다. 이 예는 소유자만 쓸 수 있고, 다른 사람은 읽기만 가능해요.', NULL, NULL, NULL, NULL),
  (129, 3, '숫자 권한 7 의 의미', '`chmod 755` 에서 첫 숫자 `7` 은 소유자에게 어떤 권한을 줄까요?', 'r=4, w=2, x=1 을 더해요.', NULL, NULL, '[]', 'choice', '["rwx (읽기+쓰기+실행)", "r-x (읽기+실행)", "rw- (읽기+쓰기)", "--x (실행만)"]', 0, '4+2+1=7 이라 rwx 입니다. 5 는 4+1 이라 r-x, 6 은 4+2 라 rw- 예요. 755 는 소유자만 쓸 수 있고 모두 실행할 수 있는 흔한 설정입니다.', NULL, NULL, NULL, NULL),
  (129, 4, 'chmod 644 의 모양', '`chmod 644 notes.txt` 를 하면 `ls -l` 에서 권한이 어떻게 보일까요?', '6=rw-, 4=r-- 이에요.', NULL, NULL, '[]', 'choice', '["`-rwxr-xr-x`", "`-rw-------`", "`-rwxrwxrwx`", "`-rw-r--r--`"]', 3, '644 는 소유자는 읽고 쓰기, 그룹과 다른 사람은 읽기만 가능합니다. 일반 파일의 가장 흔한 권한이에요.', NULL, NULL, NULL, NULL),
  (129, 5, '스크립트가 실행이 안 돼요', '`./run.sh` 를 실행했더니 `Permission denied` 가 납니다. 파일은 읽을 수 있습니다. 가장 알맞은 조치는 무엇일까요?', '실행 권한(x)이 없는 경우예요.', NULL, NULL, '[]', 'choice', '["`rm run.sh` 로 지운다", "`cat run.sh` 를 다시 한다", "`chmod +x run.sh` 로 실행 권한을 준다", "서버를 재부팅한다"]', 2, '`ls -l` 에 `x` 가 없으면 실행할 수 없습니다. `chmod +x` 는 실행 권한을 더해요. 권한 문제는 `ls -l` 로 확인하는 것이 첫걸음입니다.', NULL, NULL, NULL, NULL),
  (129, 6, '디렉터리의 x 권한', '폴더에 `x` 권한이 없으면 어떤 일이 생길까요?', '폴더에서 x 는 "안으로 들어가는 권한"이에요.', NULL, NULL, '[]', 'choice', '["폴더가 실행 파일이 된다", "그 폴더 안으로 들어가거나(cd) 안의 파일에 접근할 수 없다", "폴더 이름을 바꿀 수 없다", "폴더가 자동 삭제된다"]', 1, '폴더에서 r 은 목록 보기, w 는 파일 생성·삭제, x 는 진입입니다. 파일 권한과 의미가 조금 달라요.', NULL, NULL, NULL, NULL),
  (129, 7, 'chown 은 무엇을 할까', '`chown alice file.txt` 는 무엇을 바꿀까요?', 'change owner 의 줄임말이에요.', NULL, NULL, '[]', 'choice', '["파일의 소유자를 alice 로 바꾼다", "파일 권한을 alice 에게만 준다", "파일 이름을 alice 로 바꾼다", "파일을 alice 의 홈으로 옮긴다"]', 0, '`chown` 은 소유자, `chmod` 는 권한 비트입니다. 둘을 헷갈리지 않는 것이 중요해요. 대개 root 권한이 필요합니다.', NULL, NULL, NULL, NULL),
  (129, 8, 'sudo 는 무엇일까', '`sudo systemctl restart nginx` 에서 `sudo` 는 무엇을 해 줄까요?', '관리자 권한으로 한 번만 실행해요.', NULL, NULL, '[]', 'choice', '["서버를 새로 설치한다", "비밀번호를 삭제한다", "명령을 취소한다", "그 명령 하나를 관리자(root) 권한으로 실행한다"]', 3, '`sudo` 는 필요한 명령에만 잠깐 권한을 올립니다. 평소에는 일반 계정으로 일하고 필요한 때만 쓰는 것이 안전해요.', NULL, NULL, NULL, NULL),
  (129, 9, 'PID 는 무엇일까', '`ps` 결과의 PID 는 무엇을 뜻할까요?', '프로세스마다 붙는 번호예요.', NULL, NULL, '[]', 'choice', '["파일 크기", "포트 번호", "프로세스 ID, 실행 중인 프로그램마다 부여되는 고유 번호", "사용자 번호"]', 2, 'PID 로 프로세스를 가리켜 종료하거나(`kill PID`) 상태를 봅니다. 프로그램이 다시 시작되면 PID 도 바뀌어요.', NULL, NULL, NULL, NULL),
  (129, 10, 'kill 의 기본 신호', '`kill 1234` 를 실행하면 프로세스 1234 에 어떤 일이 일어날까요?', '기본은 부드럽게 종료를 요청해요.', NULL, NULL, '[]', 'choice', '["즉시 강제 종료된다", "정상 종료를 요청하는 신호(SIGTERM)가 간다. 프로세스가 정리하고 끝날 수 있다", "일시 정지된다", "재시작된다"]', 1, '먼저 `kill PID`(정상 종료 요청)를 쓰고, 그래도 안 끝날 때만 `kill -9 PID`(강제 종료)를 씁니다. 강제 종료는 정리 작업을 못 해서 데이터가 깨질 수 있어요.', NULL, NULL, NULL, NULL),
  (129, 11, 'Ctrl+C 와 Ctrl+Z', '실행 중인 명령을 **끝내려고** 터미널에서 누르는 키는 무엇일까요?', 'C 는 cancel 을 떠올려 보세요.', NULL, NULL, '[]', 'choice', '["Ctrl+C (현재 명령을 중단한다)", "Ctrl+Z (일시 정지시켜 백그라운드로 보낸다)", "Ctrl+D (입력의 끝을 알린다)", "Ctrl+S (저장한다)"]', 0, 'Ctrl+C 는 종료, Ctrl+Z 는 정지(`fg` 로 다시 가져올 수 있음)입니다. Ctrl+D 는 입력 끝이라 쉘이 종료돼요.', NULL, NULL, NULL, NULL),
  (129, 12, '명령 뒤의 &', '`sleep 100 &` 처럼 명령 끝에 `&` 를 붙이면 무엇이 달라질까요?', '기다리지 않고 바로 돌려받아요.', NULL, NULL, '[]', 'choice', '["명령이 두 번 실행된다", "오류가 숨겨진다", "관리자 권한으로 실행된다", "백그라운드로 실행되어 터미널을 바로 쓸 수 있다"]', 3, '`&` 는 명령을 뒤에서 돌립니다. `jobs` 로 목록을 보고 `fg` 로 앞으로 가져와요. 터미널을 닫으면 끝날 수 있어서 오래 돌릴 일은 `nohup` 이나 서비스로 합니다.', NULL, NULL, NULL, NULL),
  (129, 13, 'df 와 du 의 차이', '`df -h` 와 `du -sh 폴더` 의 차이로 알맞은 것은 무엇일까요?', 'df 는 디스크 전체, du 는 폴더가 쓴 양이에요.', NULL, NULL, '[]', 'choice', '["둘은 완전히 같다", "`df` 는 삭제, `du` 는 복사다", "`df` 는 디스크(파일시스템)의 전체·사용·남은 용량, `du` 는 특정 폴더가 차지하는 용량", "`du` 는 메모리 사용량을 보여 준다"]', 2, '디스크가 가득 찼을 때 `df -h` 로 어느 파티션인지 보고, `du -sh *` 로 어느 폴더가 큰지 찾습니다.', NULL, NULL, NULL, NULL),
  (129, 14, '파이프 | 는 무엇일까', '`cat app.log | grep ERROR` 에서 `|` 는 무엇을 할까요?', '앞 명령의 출력을 뒤 명령의 입력으로 이어 줘요.', NULL, NULL, '[]', 'choice', '["두 명령 중 하나만 실행한다", "앞 명령의 출력을 뒤 명령의 입력으로 넘긴다", "파일에 저장한다", "명령을 반복한다"]', 1, '파이프로 작은 명령들을 이어 붙이는 것이 리눅스의 강점입니다. 여기서는 로그에서 ERROR 가 든 줄만 걸러 줘요.', NULL, NULL, NULL, NULL),
  (129, 15, '권한을 숫자로', '소유자는 읽기·쓰기·실행, 그룹과 다른 사람은 읽기·실행만 가능한 권한을 숫자로 주려 합니다. 빈칸을 채우세요.', 'rwx=7, r-x=5 예요.', NULL, NULL, '[]', 'fill', '["755", "644", "777", "600"]', NULL, '`755` 는 `rwxr-xr-x` 입니다. `777` 은 모두가 쓸 수 있어 위험하니 피하세요.', '[0]', 'chmod {0} script.sh', NULL, NULL),
  (129, 16, '실행 권한 주기', '`run.sh` 에 **실행 권한만 더하는** 옵션을 채우세요.', '"실행"의 x 에 더하기를 붙여요.', NULL, NULL, '[]', 'fill', '["+x", "-x", "+w", "+r"]', NULL, '`+x` 는 실행 권한을 더하고, `-x` 는 뺍니다. 기존 다른 권한은 그대로예요.', '[0]', 'chmod {0} run.sh', NULL, NULL),
  (129, 17, '소유자 바꾸기', '`app.log` 의 소유자를 `deploy` 로 바꾸는 명령입니다. 빈칸을 채우세요.', 'change owner 의 줄임말이에요.', NULL, NULL, '[]', 'fill', '["chown", "chmod", "chgrp", "chroot"]', NULL, '`chown 소유자:그룹 파일` 로 소유자와 그룹을 함께 바꿀 수도 있습니다.', '[0]', '{0} deploy app.log', NULL, NULL),
  (129, 18, '프로세스 목록 보기', '실행 중인 **모든 프로세스**를 자세히 보는 흔한 명령입니다. 옵션을 채우세요.', '"all users"를 뜻하는 글자들이 이어져 있어요.', NULL, NULL, '[]', 'fill', '["aux", "abc", "xyz", "zip"]', NULL, '`ps aux` 는 모든 사용자의 프로세스를 CPU·메모리와 함께 보여 줍니다. `ps aux | grep nginx` 로 찾아요.', '[0]', 'ps {0}', NULL, NULL),
  (129, 19, '프로세스 정상 종료', 'PID 가 `1234` 인 프로세스에게 **종료를 정중히 요청**하는 명령입니다. 빈칸을 채우세요.', '옵션 없이 쓰면 기본 신호(TERM)가 가요.', NULL, NULL, '[]', 'fill', '["kill", "kill -9", "killall -9", "stop"]', NULL, '먼저 `kill 1234` 로 정중히 요청하세요. `kill -9` 는 마지막 수단입니다.', '[0]', '{0} 1234', NULL, NULL),
  (129, 20, '강제 종료', '정상 종료 요청에도 끝나지 않는 PID `1234` 를 **강제로** 끝내는 명령입니다. 빈칸을 채우세요.', '강제 종료 신호의 번호예요.', NULL, NULL, '[]', 'fill', '["-9", "-1", "-15", "-0"]', NULL, '`-9`(SIGKILL)는 프로세스가 막을 수 없는 강제 종료입니다. 정리 작업을 못 하니 먼저 정상 종료를 시도하세요.', '[0]', 'kill {0} 1234', NULL, NULL),
  (129, 21, '디스크 용량 보기', '디스크 **전체 사용량과 남은 용량**을 사람이 읽기 쉽게 보는 명령입니다. 빈칸을 채우세요.', 'disk free 의 줄임말이에요.', NULL, NULL, '[]', 'fill', '["df", "du", "ls", "free"]', NULL, '`df -h` 는 파티션별 사용량(`Use%`)을 보여 줍니다. 가득 찬 곳을 찾을 때 첫 명령이에요.', '[0]', '{0} -h', NULL, NULL),
  (129, 22, '메모리 보기', '시스템의 **메모리 사용량**을 사람이 읽기 쉽게 보는 명령입니다. 빈칸을 채우세요.', '"비어 있는"을 뜻하는 영어 단어예요.', NULL, NULL, '[]', 'fill', '["free", "df", "du", "mem"]', NULL, '`free -h` 의 `available` 이 새 프로그램이 쓸 수 있는 메모리입니다. 숫자가 작아도 `buff/cache` 는 필요하면 비워지는 영역이에요.', '[0]', '{0} -h', NULL, NULL),
  (129, 23, '줄 수 세기', '`grep ERROR app.log` 결과가 **몇 줄**인지 세려고 파이프로 이어 붙입니다. 빈칸을 채우세요.', '단어·줄·글자를 세는 명령이에요.', NULL, NULL, '[]', 'fill', '["wc", "sort", "cut", "tr"]', NULL, '`wc -l` 은 줄 수를 셉니다. `grep 패턴 파일 | wc -l` 은 에러 개수를 세는 대표 조합이에요.', '[0]', 'grep ERROR app.log | {0} -l', NULL, NULL),
  (129, 24, '정렬하기', '`names.txt` 의 줄을 **알파벳순으로 정렬**해 보여 주는 명령입니다. 빈칸을 채우세요.', '"정렬하다"를 뜻하는 영어 단어예요.', NULL, NULL, '[]', 'fill', '["sort", "uniq", "cut", "wc"]', NULL, '`sort` 는 정렬합니다. 숫자 크기순은 `sort -n`, 거꾸로는 `sort -r` 이에요.', '[0]', '{0} names.txt', NULL, NULL),
  (129, 25, '중복 세기', '정렬된 입력에서 **같은 줄이 몇 번 나왔는지** 세어 앞에 숫자를 붙이는 옵션을 채우세요.', 'count 의 첫 글자예요.', NULL, NULL, '[]', 'fill', '["-c", "-d", "-u", "-i"]', NULL, '`uniq` 는 이웃한 같은 줄만 합치므로 먼저 `sort` 해야 합니다. `sort | uniq -c | sort -rn` 은 빈도 순위를 만드는 유명한 조합이에요.', '[0]', 'sort names.txt | uniq {0}', NULL, NULL),
  (129, 26, '구분자로 칸 뽑기', '`a,b,c` 처럼 쉼표로 나뉜 줄에서 **두 번째 칸**을 뽑는 명령입니다. 빈칸을 채우세요.', '구분자는 delimiter, 칸은 field 예요.', NULL, NULL, '[]', 'fill', '["-f", "-c", "-n", "-s"]', NULL, '`cut -d 구분자 -f 번호` 는 칸을 뽑습니다. 공백으로 나뉘는 로그에는 `awk ''{print $2}''` 가 편해요.', '[0]', 'echo ''a,b,c'' | cut -d, {0}2', NULL, NULL),
  (129, 27, '앞 3줄만 보기', '파일의 **처음 3줄**만 보는 명령입니다. 빈칸을 채우세요.', '머리를 뜻하는 영어 단어예요.', NULL, NULL, '[]', 'fill', '["head", "tail", "less", "cat"]', NULL, '`head` 는 앞부분, `tail` 은 뒷부분입니다. `tail -n 3` 은 마지막 3줄이에요.', '[0]', '{0} -n 3 app.log', NULL, NULL),
  (129, 28, '스크립트에 권한 주고 실행하기', '새로 만든 스크립트가 실행이 안 될 때의 순서입니다. 순서에 맞게 놓아 보세요.', '증상 확인 → 권한 확인 → 수정 → 실행 순서예요.', NULL, NULL, '[]', 'order', '["`./run.sh` 를 실행해 `Permission denied` 를 확인한다", "`ls -l run.sh` 로 권한을 본다", "`chmod +x run.sh` 로 실행 권한을 준다", "`./run.sh` 를 다시 실행한다"]', NULL, '오류 메시지를 읽고, 원인을 확인하고, 고치고, 다시 시도하는 것이 문제 해결의 기본 흐름입니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (129, 29, '멈춘 프로세스 종료하기', '응답 없는 프로세스를 끝내는 순서입니다. 순서에 맞게 놓아 보세요.', '찾기 → 정중히 → 확인 → 강제 순서예요.', NULL, NULL, '[]', 'order', '["`ps aux | grep 이름` 으로 PID 를 찾는다", "`kill PID` 로 정상 종료를 요청한다", "`ps aux | grep 이름` 으로 끝났는지 확인한다", "안 끝났으면 `kill -9 PID` 로 강제 종료한다"]', NULL, '바로 `kill -9` 를 쓰지 않는 것이 중요합니다. 먼저 정상 종료를 시도해야 데이터가 안전해요.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (129, 30, '로그에서 에러 개수 세는 흐름', '로그에서 ERROR 가 든 줄의 개수를 세는 순서입니다. 순서에 맞게 놓아 보세요.', '파일 확인 → 걸러내기 → 세기 순서예요.', NULL, NULL, '[]', 'order', '["`ls -l app.log` 로 파일이 있는지 본다", "`head app.log` 로 형식을 본다", "`grep ERROR app.log` 로 에러 줄을 걸러 본다", "`grep ERROR app.log | wc -l` 로 개수를 센다"]', NULL, '결과를 눈으로 먼저 보고 나서 세면 잘못된 패턴으로 센 숫자를 믿는 실수를 줄일 수 있어요.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (129, 31, '디스크가 찼을 때 찾는 순서', '서버 디스크가 가득 찼다는 알림이 왔습니다. 순서에 맞게 놓아 보세요.', '어느 디스크 → 어느 폴더 → 정리 순서예요.', NULL, NULL, '[]', 'order', '["`df -h` 로 가득 찬 파티션을 찾는다", "`du -sh /var/*` 로 큰 폴더를 찾는다", "더 깊이 들어가 큰 파일을 찾는다", "필요 없는 것을 정리하고 `df -h` 로 다시 확인한다"]', NULL, '큰 범위에서 작은 범위로 좁혀 가면 길을 잃지 않습니다. 정리한 뒤 다시 확인하는 것도 잊지 마세요.', '[0, 1, 2, 3]', NULL, NULL, NULL);
